// ── L3: Insert device_log ───────────────────────────────────
if (!msg._state_changed) {
    node.status({ fill: 'grey', shape: 'dot', text: 'no change' });
    return null;
}

const d = msg.device;
msg.topic = `INSERT INTO device_log (ts, device_id, device_type, location, payload, event) VALUES (?,?,?,?,?,?)`;
msg.payload = [
    d.ts,
    d.id,
    d.type,
    d.location,
    JSON.stringify(d.state),
    msg.event_type ?? 'state_change'
];

node.status({ fill: 'green', shape: 'dot', text: `log: ${d.id}` });
return msg;

// ── L3: Insert LWT gateway log ───────────────────────────────
const gateway   = msg._lwt_gateway;
const isOnline  = msg._lwt_online;
const devCount  = msg._lwt_dev_count || 0;

msg.topic   = 'INSERT INTO device_log (ts, device_id, device_type, location, payload, event) VALUES (?,?,?,?,?,?)';
msg.payload = [
    new Date().toISOString(),
    gateway,
    'gateway',
    '',
    JSON.stringify({ online: isOnline, devices_affected: devCount }),
    isOnline ? 'gateway_online' : 'gateway_offline'
];

node.status({ fill: isOnline ? 'green' : 'red', shape: 'dot', text: `${gateway}: ${isOnline ? 'ONLINE' : 'OFFLINE'}` });
return msg;
